<?php $root='../../';require '../../includes/header.php';$id=(int)($_GET['id']??0);$r=['tipo_documento'=>'CC','documento'=>'','nombre'=>'','ficha'=>'','programa'=>'','convocatoria_id'=>'','estado'=>'Activo','fecha_ingreso'=>date('Y-m-d')];if($id){$s=$pdo->prepare('SELECT * FROM beneficiarios WHERE id=?');$s->execute([$id]);$r=$s->fetch()?:$r;}if($_SERVER['REQUEST_METHOD']==='POST'){$v=[$_POST['tipo_documento'],trim($_POST['documento']),trim($_POST['nombre']),trim($_POST['ficha']),trim($_POST['programa']),$_POST['convocatoria_id']?:null,$_POST['estado'],$_POST['fecha_ingreso']?:null];if($id)$pdo->prepare('UPDATE beneficiarios SET tipo_documento=?,documento=?,nombre=?,ficha=?,programa=?,convocatoria_id=?,estado=?,fecha_ingreso=? WHERE id=?')->execute([...$v,$id]);else $pdo->prepare('INSERT INTO beneficiarios(tipo_documento,documento,nombre,ficha,programa,convocatoria_id,estado,fecha_ingreso) VALUES(?,?,?,?,?,?,?,?)')->execute($v);header('Location:index.php');exit;}$cs=$pdo->query('SELECT * FROM convocatorias ORDER BY nombre')->fetchAll();?><h2><?=$id?'Editar':'Nuevo'?> beneficiario</h2><form method="post" class="card p-4 mt-3"><div class="row g-3"><div class="col-md-2"><label class="form-label">Tipo</label><select name="tipo_documento" class="form-select"><?php foreach(['CC','TI','CE','PEP'] as $x):?><option <?=$r['tipo_documento']===$x?'selected':''?>><?=$x?></option><?php endforeach?></select></div><div class="col-md-4"><label class="form-label">Documento</label><input required name="documento" class="form-control" value="<?=htmlspecialchars($r['documento'])?>"></div><div class="col-md-6"><label class="form-label">Nombre</label><input required name="nombre" class="form-control" value="<?=htmlspecialchars($r['nombre'])?>"></div><div class="col-md-4"><label class="form-label">Ficha</label><input name="ficha" class="form-control" value="<?=htmlspecialchars($r['ficha']??'')?>"></div><div class="col-md-8"><label class="form-label">Programa</label><input name="programa" class="form-control" value="<?=htmlspecialchars($r['programa']??'')?>"></div><div class="col-md-5"><label class="form-label">Convocatoria</label><select name="convocatoria_id" class="form-select"><option value="">Sin asignar</option><?php foreach($cs as $c):?><option value="<?=$c['id']?>" <?=$r['convocatoria_id']==$c['id']?'selected':''?>><?=htmlspecialchars($c['nombre'])?></option><?php endforeach?></select></div><div class="col-md-3"><label class="form-label">Estado</label><select name="estado" class="form-select"><?php foreach(['Activo','Suspendido','Retirado','Finalizado'] as $x):?><option <?=$r['estado']===$x?'selected':''?>><?=$x?></option><?php endforeach?></select></div><div class="col-md-4"><label class="form-label">Ingreso</label><input type="date" name="fecha_ingreso" class="form-control" value="<?=$r['fecha_ingreso']?>"></div></div><div class="mt-4"><button class="btn btn-primary">Guardar</button> <a class="btn btn-light" href="index.php">Cancelar</a></div></form><?php require '../../includes/footer.php';?>